Here's a custom React hook called `useMergeState` that allows you to merge a new state object with the current one, or pass a function that receives the current state and returns a new state to be merged.

```jsx
import { useState, useCallback } from 'react';

/**
 * Custom hook that supports merging state updates
 * @param {Object} initialState - The initial state object
 * @returns {Array} [state, setState] - State and setter function
 */
export function useMergeState(initialState) {
  const [state, setState] = useState(initialState);

  const mergeState = useCallback((updater) => {
    setState(prevState => {
      if (typeof updater === 'function') {
        const newState = updater(prevState);
        return { ...prevState, ...newState };
      } else {
        return { ...prevState, ...updater };
      }
    });
  }, []);

  return [state, mergeState];
}
```

### Usage Examples

```jsx
import React from 'react';
import { useMergeState } from './useMergeState';

function UserProfile() {
  const [user, setUser] = useMergeState({
    name: 'Alice',
    email: 'alice@example.com',
    age: 30
  });

  const updateName = () => {
    setUser({ name: 'Bob' }); // Partial merge
  };

  const updateAge = () => {
    setUser(prev => ({ ...prev, age: prev.age + 1 })); // Function-based update
  };

  const resetEmail = () => {
    setUser(prev => ({ ...prev, email: '' })); // Function to clear email
  };

  return (
    <div>
      <h2>User Profile</h2>
      <p>Name: {user.name}</p>
      <p>Email: {user.email}</p>
      <p>Age: {user.age}</p>
      <button onClick={updateName}>Update Name</button>
      <button onClick={updateAge}>Increment Age</button>
      <button onClick={resetEmail}>Clear Email</button>
    </div>
  );
}
```

### Key Features

- ✅ Supports both object and function-based updates
- ✅ Deep merge behavior for partial state updates
- ✅ Compatible with functional state updates
- ✅ Easy to extend for nested or complex state logic

### Optional: Deep Merge Version

If your state contains nested objects and you need deep merging, you can extend the hook with a deep merge utility:

```jsx
function deepMerge(target, source) {
  const output = { ...target };
  for (const key in source) {
    if (source[key] instanceof Object && key in target) {
      output[key] = deepMerge(target[key], source[key]);
    } else {
      output[key] = source[key];
    }
  }
  return output;
}

export function useDeepMergeState(initialState) {
  const [state, setState] = useState(initialState);

  const deepMergeState = useCallback((updater) => {
    setState(prevState => {
      const newState = typeof updater === 'function' ? updater(prevState) : updater;
      return deepMerge(prevState, newState);
    });
  }, []);

  return [state, deepMergeState];
}
```

### When to Use

- ✅ Use `useMergeState` for simple or shallow state merging
- ✅ Use `useDeepMergeState` if your state includes deeply nested structures and you need recursive merging

This hook provides a flexible and clean way to manage object-based state in functional components, combining the simplicity of `useState` with the power of partial and functional updates.
